namespace LWS.TruckVolleyball.Editor
{
 public static class VolleyAuthoring
 {
  public const string Folder="TruckVolleyball",Scene="Assets/TruckVolleyball/Scenes/TruckVolleyball.unity";
  public static void Create()
  {
   if(File.Exists(Scene))throw new InvalidOperationException("Preserve the authored beach court; use targeted upgrades.");var m=SportsEventAuthoring.Begin<VolleyMatch>(Folder);m.teamA=m.teamB=2;m.option=1;m.NormalizeSetup();m.feedback.clips=LWS.TruckHockey.Editor.HockeyAudioAuthoring.Create();
   var sand=SportsEventAuthoring.Mat(Folder,"Sunlit actual Vista volleyball sand",new Color(.82f,.66f,.42f),.06f);var layer=AssetDatabase.LoadAssetAtPath<TerrainLayer>("Assets/PinwheelStudio/Vista/Personal/Samples/TerrainLayers/Sand/Sand_VistaSample.terrainlayer");if(layer==null)throw new InvalidOperationException("Installed beach surface required");sand.mainTexture=layer.diffuseTexture;sand.mainTextureScale=Vector2.one*26;if(layer.normalMapTexture!=null){sand.SetTexture("_BumpMap",layer.normalMapTexture);sand.EnableKeyword("_NORMALMAP");sand.SetFloat("_BumpScale",.45f);}
   var contact=SportsEventAuthoring.Contact(Folder,"Truck beach sand contact",.8f,.03f);var floor=SportsEventAuthoring.Box("Continuous volleyball sand court",new Vector3(0,-.5f,0),new Vector3(500,1,600),sand,contact);SportsDrivingSurfaceAuthoring.MarkHierarchy(floor.transform);
   var cream=SportsEventAuthoring.Mat(Folder,"Weathered ivory boundary ropes",new Color(.97f,.91f,.73f),.1f);var blue=SportsEventAuthoring.Mat(Folder,"Scuffed lagoon blue",new Color(.025f,.58f,.76f),.3f);var orange=SportsEventAuthoring.Mat(Folder,"Sun faded coral orange",new Color(.98f,.3f,.05f),.3f);var wood=AssetDatabase.LoadAssetAtPath<Material>("Assets/TruckJousting/Materials/Worn oak lance grain.mat");if(wood==null)wood=cream;
   foreach(int side in new[]{-1,1}){SportsEventAuthoring.Box("Inset actual court sideline",new Vector3(side*32,.045f,0),new Vector3(.5f,.07f,100),blue);SportsEventAuthoring.Box("Inset actual court baseline",new Vector3(0,.045f,side*50),new Vector3(64,.07f,.5f),blue);SportsEventAuthoring.Box("Actual attack line",new Vector3(0,.045f,side*16),new Vector3(64,.07f,.22f),side<0?blue:orange);SportsEventAuthoring.Box("Visible outer spectator safety barrier",new Vector3(side*74,1,0),new Vector3(.8f,2,150),wood,contact);}
   m.net=new GameObject("Giant woven truck volleyball net assembly").transform;
   foreach(int side in new[]{-1,1}){SportsEventAuthoring.Box("Oversized wooden net mast",new Vector3(side*36,5,0),new Vector3(.9f,10,.9f),wood,contact,m.net);SportsEventAuthoring.Box("Padded volleyball mast base",new Vector3(side*36,1.5f,0),new Vector3(1.7f,3,1.7f),side<0?blue:orange,contact,m.net);}
   var weave=SportsEventAuthoring.Mat(Folder,"Dark readable woven net",new Color(.07f,.13f,.16f),.1f);
   for(int i=0;i<=36;i++)Rope(m.net,new Vector3(-36+i*2,.6f,0),new Vector3(-36+i*2,7,0),.075f,weave);
   for(int row=0;row<=8;row++)Rope(m.net,new Vector3(-36,.6f+row*.8f,0),new Vector3(36,.6f+row*.8f,0),row==8?.15f:.075f,row==8?cream:weave);
   var net=new GameObject("Physical woven volleyball net");net.transform.SetParent(m.net,false);net.transform.position=new Vector3(0,3.8f,0);var netShape=net.AddComponent<BoxCollider>();netShape.size=new Vector3(72,6.4f,.22f);netShape.sharedMaterial=SportsEventAuthoring.Contact(Folder,"Soft deadening woven net",.25f,.1f);
   var ball=GameObject.CreatePrimitive(PrimitiveType.Sphere);ball.name="Actual enormous striped inflatable beach volleyball";ball.transform.localScale=Vector3.one;ball.transform.position=new Vector3(0,3.15f,-39);ball.GetComponent<SphereCollider>().radius=3;
   var original=ball.GetComponent<MeshFilter>().sharedMesh;var mesh=UnityEngine.Object.Instantiate(original);mesh.name="Original striped beach ball shell";var triangles=mesh.triangles;var vertices=mesh.vertices;var stripes=new List<int>[6];for(int i=0;i<6;i++)stripes[i]=new List<int>();for(int i=0;i<triangles.Length;i+=3){var center=(vertices[triangles[i]]+vertices[triangles[i+1]]+vertices[triangles[i+2]])/3;int stripe=Mathf.Clamp((int)((Mathf.Atan2(center.z,center.x)+Mathf.PI)/(2*Mathf.PI)*6),0,5);stripes[stripe].AddRange(new[]{triangles[i],triangles[i+1],triangles[i+2]});}mesh.vertices=vertices.Select(v=>v*6).ToArray();mesh.subMeshCount=6;for(int i=0;i<6;i++)mesh.SetTriangles(stripes[i],i);mesh.RecalculateBounds();Directory.CreateDirectory("Assets/"+Folder+"/Models");AssetDatabase.CreateAsset(mesh,"Assets/"+Folder+"/Models/Original striped beach ball.asset");ball.GetComponent<MeshFilter>().sharedMesh=mesh;ball.GetComponent<Renderer>().sharedMaterials=new[]{blue,cream,orange,blue,cream,orange};ball.GetComponent<Collider>().sharedMaterial=SportsEventAuthoring.Contact(Folder,"Inflatable physical beach ball",.08f,.72f);
   m.ball=ball.AddComponent<Rigidbody>();m.ball.mass=80;m.ball.linearDamping=.07f;m.ball.angularDamping=.1f;m.ball.maxLinearVelocity=32;m.ball.maxAngularVelocity=12;m.ball.interpolation=RigidbodyInterpolation.Interpolate;m.ball.collisionDetectionMode=CollisionDetectionMode.ContinuousDynamic;m.ball.solverIterations=18;m.ball.isKinematic=true;ball.AddComponent<VolleyBallContact>().match=m;
   m.trucks=new SportsEventTruck[8];m.fragments=new SportsFragmentRig[8];for(int i=0;i<8;i++){var truck=FareFightVehicleAuthoring.Spawn(m,i,new Vector3((i%4-1.5f)*13,.65f,i<4?-30:30),Quaternion.Euler(0,i<4?0:180,0));m.trucks[i]=truck;truck.body.maxLinearVelocity=32;truck.body.maxAngularVelocity=4;m.fragments[i]=SportsFragmentAuthoring.InstallRigid(truck.body,truck.visuals.GetComponentsInChildren<MeshFilter>(true),Folder);}
   Venue(m,wood,cream);m.broadcast=SportsEventAuthoring.Camera("Beach volleyball whole rally broadcast");m.broadcast.view.farClipPlane=2400;m.broadcast.view.orthographic=true;m.framing=m.broadcast.gameObject.AddComponent<SportsCameraFit>();m.framing.cameraTarget=m.broadcast.view;m.framing.arenaFit=true;m.framing.topInset=.1f;m.framing.bottomInset=.2f;m.cameras=new[]{m.broadcast.view};
   SportsEventAuthoring.UI(m);SportsRallyAuthoring.CompactUI(m);m.drivingViews=SportsDrivingViewsAuthoring.Install(m,m.trucks,m.broadcast,Folder);m.drivingViews.independentViewModes=true;m.atmosphere=SportsChaosAuthoring.Weather(m,Folder);m.atmosphere.presets=SportsWeatherPresetsAuthoring.EnsureCatalog();m.drivingViews.rally.weather=m.atmosphere;SportsWeatherPickerAuthoring.Install(m,m.atmosphere.presets,new Vector2(350,-180));var hud=m.gameObject.AddComponent<SportsExpansionViewHud>();hud.match=m;hud.views=m.drivingViews;SportsUIAuthoring.Button(m.menus.pages[6].transform,"WATCH THE RALLY","watchvolley",new Vector2(0,-245),new Vector2(520,48));Artwork(m);SportsBroadcastAuthoring.ApplyScene();SportsScenicGradeAuthoring.Install(m.gameObject,new[]{m.broadcast.view}.Concat(m.drivingViews.rally.views.Select(v=>v.view)).ToArray(),Folder,-.2f);SportsEventAuthoring.Save(Folder);
  }
  public static void UpgradePresentation()
  {
   EditorSceneManager.OpenScene(Scene);var m=UnityEngine.Object.FindAnyObjectByType<VolleyMatch>();var sand=AssetDatabase.LoadAssetAtPath<Material>("Assets/"+Folder+"/Materials/Sunlit actual Vista volleyball sand.mat");sand.color=new Color(.82f,.66f,.42f);EditorUtility.SetDirty(sand);
   var blue=AssetDatabase.LoadAssetAtPath<Material>("Assets/"+Folder+"/Materials/Scuffed lagoon blue.mat");var weave=SportsEventAuthoring.Mat(Folder,"Dark readable woven net",new Color(.07f,.13f,.16f),.1f);
   foreach(var go in SceneManager.GetActiveScene().GetRootGameObjects())if(go.name=="Inset actual court sideline"||go.name=="Inset actual court baseline"){go.GetComponent<Renderer>().sharedMaterial=blue;var size=go.transform.localScale;if(go.name.EndsWith("sideline"))size.x=.5f;else size.z=.5f;go.transform.localScale=size;}
   foreach(var line in m.net.GetComponentsInChildren<LineRenderer>())if(line.widthMultiplier<.1f){line.sharedMaterial=weave;line.widthMultiplier=.075f;}
   var root=GameObject.Find("Installed tropical resort palms and audience").transform;var dest=SceneManager.GetActiveScene();var source=EditorSceneManager.OpenScene(LWS.TruckLimbo.Editor.LimboAuthoring.Scene,OpenSceneMode.Additive);
   try{SceneManager.SetActiveScene(dest);var dressing=source.GetRootGameObjects().First(x=>x.name.StartsWith("Tropical limbo party"));foreach(Transform item in dressing.transform)if(item.GetComponentsInChildren<Transform>(true).Any(t=>t.name.IndexOf("Palm",StringComparison.OrdinalIgnoreCase)>=0)){var copy=SportsReplayVisuals.Copy(item);copy.name="Corrected installed resort palm";copy.transform.SetParent(root,true);var p=copy.transform.position;p.x=Mathf.Sign(p.x)*49;copy.transform.position=p;}}finally{EditorSceneManager.CloseScene(source,true);SceneManager.SetActiveScene(dest);}
   foreach(var go in dest.GetRootGameObjects())if(go.name=="Original volleyball resort venue artwork"){int side=go.transform.position.x<0?-1:1;go.transform.position=new Vector3(0,.065f,side*57);go.transform.rotation=Quaternion.Euler(90,side<0?0:180,0);}
   var text=GameObject.Find("Actual match scoreboard typography").GetComponent<TMP_Text>();text.fontSize=24;text.enableAutoSizing=true;text.fontSizeMax=26;text.fontSizeMin=14;EditorUtility.SetDirty(text);EditorSceneManager.SaveScene(dest);AssetDatabase.SaveAssets();
  }
  static void Rope(Transform parent,Vector3 a,Vector3 b,float width,Material material){var line=new GameObject("Modeled woven volleyball rope").AddComponent<LineRenderer>();line.transform.SetParent(parent,false);line.useWorldSpace=false;line.positionCount=2;line.SetPosition(0,a);line.SetPosition(1,b);line.widthMultiplier=width;line.sharedMaterial=material;}
  static void Venue(VolleyMatch m,Material wood,Material cream)
  {
   var root=new GameObject("Installed tropical resort palms and audience").transform;var dest=SceneManager.GetActiveScene();var limbo=EditorSceneManager.OpenScene(LWS.TruckLimbo.Editor.LimboAuthoring.Scene,OpenSceneMode.Additive);
   try{SceneManager.SetActiveScene(dest);var dressing=limbo.GetRootGameObjects().First(x=>x.name.StartsWith("Tropical limbo party"));foreach(Transform item in dressing.transform)if(item.GetComponentsInChildren<Transform>(true).Any(t=>t.name.IndexOf("Palm",StringComparison.OrdinalIgnoreCase)>=0)){var copy=SportsReplayVisuals.Copy(item);copy.transform.SetParent(root,true);var pos=copy.transform.position;pos.x=Mathf.Sign(pos.x)*49;copy.transform.position=pos;}}finally{EditorSceneManager.CloseScene(limbo,true);SceneManager.SetActiveScene(dest);}
   var source=EditorSceneManager.OpenScene(LWS.TruckHotPotato.Editor.HotPotatoAuthoring.Scene,OpenSceneMode.Additive);
   try{SceneManager.SetActiveScene(dest);var donor=source.GetRootGameObjects().SelectMany(x=>x.GetComponentsInChildren<LWS.TruckHotPotato.HotPotatoMatch>(true)).First().crowd;m.crowd=m.gameObject.AddComponent<LWS.TruckFieldGoal.FieldGoalCrowd>();m.crowd.eventSession=m;m.crowd.nearFans=Array.Empty<Animator>();m.crowd.batches=new LWS.TruckFieldGoal.FieldGoalCrowd.Batch[donor.batches.Length];
    for(int v=0;v<donor.batches.Length;v++){var original=donor.batches[v];var fans=new List<MeshFilter>();var seats=new List<Matrix4x4>();for(int side=-1;side<=1;side+=2)for(int row=0;row<4;row++)for(int k=v;k<36;k+=donor.batches.Length){var p=new Vector3(side*(65+row*2),1.75f+row,-43+k*2.4f);var rotation=Quaternion.Euler(0,side<0?90:-90,0);var fan=new GameObject("Reused posed beach spectator");fan.transform.SetParent(root);fan.transform.SetPositionAndRotation(p,rotation);var mesh=fan.AddComponent<MeshFilter>();mesh.sharedMesh=original.idle;fan.AddComponent<MeshRenderer>().sharedMaterials=original.materials;fans.Add(mesh);seats.Add(Matrix4x4.TRS(p,rotation,Vector3.one));}m.crowd.batches[v]=new LWS.TruckFieldGoal.FieldGoalCrowd.Batch{idle=original.idle,cheer=original.cheer,materials=original.materials,fans=fans.ToArray(),seats=seats.ToArray()};}
    m.crowd.response=m.gameObject.AddComponent<AudioSource>();m.crowd.response.playOnAwake=false;m.crowd.response.spatialBlend=0;m.crowd.cheer=donor.cheer;m.crowd.boo=donor.boo;
   }finally{EditorSceneManager.CloseScene(source,true);SceneManager.SetActiveScene(dest);}
   foreach(int side in new[]{-1,1})for(int row=0;row<4;row++)SportsEventAuthoring.Box("Tropical timber spectator terrace",new Vector3(side*(65+row*2),1+row,0),new Vector3(2.5f,1.5f,90),wood,null,root);
   var panel=SportsEventAuthoring.Box("Finished resort rally scoreboard",new Vector3(0,14,72),new Vector3(64,14,1),SportsEventAuthoring.Mat(Folder,"Dark scoreboard enamel",new Color(.02f,.06f,.08f),.3f));foreach(int side in new[]{-1,1})SportsEventAuthoring.Box("Scoreboard timber support",new Vector3(side*28,6,72),new Vector3(1.5f,12,1.5f),wood);
   var text=new GameObject("Actual match scoreboard typography").AddComponent<TextMeshPro>();text.font=Resources.Load<SportsBroadcastTheme>("SportsBroadcastTheme").headingFont;text.transform.position=new Vector3(0,14,71.4f);text.rectTransform.sizeDelta=new Vector2(60,12);text.fontSize=24;text.enableAutoSizing=true;text.fontSizeMax=26;text.fontSizeMin=14;text.alignment=TextAlignmentOptions.Center;text.color=cream.color;var board=panel.AddComponent<VolleyBoard>();board.match=m;board.text=text;
  }
  static void Artwork(VolleyMatch m)
  {
   var logo=SportsRetroMenuAuthoring.LoadLogo(Folder);
   foreach(int index in new[]{0,4}){var page=m.menus.pages[index];var art=SportsUIAuthoring.Rect("Original sport title artwork",page.transform,new Vector2(260,160),new Vector2(-560,365)).AddComponent<UnityEngine.UI.Image>();art.sprite=logo;art.preserveAspect=true;art.raycastTarget=false;var title=page.transform.Find("Title").GetComponent<TMP_Text>();title.rectTransform.anchoredPosition+=Vector2.right*140;title.rectTransform.sizeDelta=new Vector2(1000,title.rectTransform.sizeDelta.y);}
   var material=SportsEventAuthoring.Mat(Folder,"Original grungy beach event signage",Color.white);material.shader=Shader.Find("Universal Render Pipeline/Unlit");material.mainTexture=logo.texture;material.SetFloat("_Surface",1);material.SetFloat("_SrcBlend",5);material.SetFloat("_DstBlend",10);material.SetFloat("_ZWrite",0);material.EnableKeyword("_SURFACE_TYPE_TRANSPARENT");material.renderQueue=3000;
   foreach(int side in new[]{-1,1}){var sign=GameObject.CreatePrimitive(PrimitiveType.Quad);sign.name="Original volleyball resort venue artwork";UnityEngine.Object.DestroyImmediate(sign.GetComponent<Collider>());sign.transform.position=new Vector3(0,.065f,side*57);sign.transform.rotation=Quaternion.Euler(90,side<0?0:180,0);sign.transform.localScale=new Vector3(30,17,1);sign.GetComponent<Renderer>().sharedMaterial=material;}
  }
 }
